export function createOptimisticStore(initialState) {
  let base = initialState;
  let visible = initialState;
  let pending = new Map();
  const subscriptions = new Set();

  function replay(baseState, changes) {
    let state = baseState;
    for (const update of changes.values()) {
      state = update(state);
    }
    return state;
  }

  function notify() {
    // Snapshot subscriptions so unsubscription cannot disrupt iteration.
    for (const { listener } of Array.from(subscriptions)) {
      try {
        listener();
      } catch {
        // A failing listener must not prevent other notifications.
      }
    }
  }

  return {
    getState() {
      return visible;
    },

    apply(id, update) {
      if (pending.has(id)) {
        throw new Error("A pending change with this id already exists.");
      }

      const nextVisible = update(visible);

      pending.set(id, update);
      visible = nextVisible;
      notify();
    },

    confirm(id) {
      if (!pending.has(id)) {
        return false;
      }

      const update = pending.get(id);
      const nextPending = new Map(pending);
      nextPending.delete(id);

      const nextBase = update(base);
      const nextVisible = replay(nextBase, nextPending);

      // Commit only after every update has completed successfully.
      base = nextBase;
      pending = nextPending;
      visible = nextVisible;

      notify();
      return true;
    },

    rollback(id) {
      if (!pending.has(id)) {
        return false;
      }

      const nextPending = new Map(pending);
      nextPending.delete(id);
      const nextVisible = replay(base, nextPending);

      pending = nextPending;
      visible = nextVisible;

      notify();
      return true;
    },

    subscribe(listener) {
      // Each subscription is independent, even for the same listener.
      const subscription = { listener };
      subscriptions.add(subscription);

      return () => {
        subscriptions.delete(subscription);
      };
    },
  };
}
